def str_to_tuple(s: str) -> tuple:
    """Convert a string of comma-separated integers into a tuple of integers."""
    if not s:
        return ()
    parts = s.split(',')
    result = []
    for part in parts:
        # Remove any leading/trailing whitespace
        cleaned = part.strip()
        if cleaned:  # skip empty parts (e.g., trailing comma)
            result.append(int(cleaned))
    return tuple(result)
